SELECT count(*) FROM users WHERE (?1 = '' OR lower(coalesce(username,'')) LIKE '%' || lower(ltrim(?1,'@')) || '%' OR lower(coalesce(first_name,'')) LIKE '%' || lower(?1) || '%') AND (?2 = 'all' OR role = ?2) AND (?3='all' OR (?3='active' AND role NOT IN ('restricted','banned') AND (ban_until IS NULL OR ban_until <= CAST(unixepoch('subsec')*1000000 AS INTEGER))) OR (?3='restricted' AND role='restricted') OR (?3='banned' AND (role='banned' OR ban_until > CAST(unixepoch('subsec')*1000000 AS INTEGER))));